+}
+
+func TestNewTrailUpdateCmdBranchFlags(t *testing.T) {
+	t.Parallel()
+	cmd := newTrailUpdateCmd()
+	for _, name := range []string{"set-branch", "trail", "branch-action", "branch"} {
